// Child Component
function CourseCard({ title, chapters, level }) {
  return (
    <div className="card">
      <h3>{title}</h3>
      <p>{chapters} chapters • {level}</p>
    </div>
  );
}

// Parent Component
function App() {
  return (
    <div>
      <CourseCard title="HTML" chapters={22} level="Beginner" />
      <CourseCard title="CSS" chapters={27} level="Intermediate" />
      <CourseCard title="JavaScript" chapters={36} level="Advanced" />
    </div>
  );
}

function Badge({ text = 'New', color = 'blue' }) {
  return (
    <span style={{ backgroundColor: color, color: 'white', padding: '4px 8px', borderRadius: '4px' }}>
      {text}
    </span>
  );
}

// Usage
<Badge />                    // shows 'New' in blue
<Badge text="Hot" color="red" />  // shows 'Hot' in red
